import { Router } from 'express';
import Student from '../models/Student.js';
import authMiddleware from '../middleware/authMiddleware.js';
import { explainFlags } from '../services/antiCheatService.js';
import requireAdminKey from '../middleware/adminKeyMiddleware.js';
import { createRequestRateLimiter } from '../middleware/requestRateLimitMiddleware.js';
import {
  buildLeaderboardCacheKey,
  getCachedLeaderboard,
  setCachedLeaderboard,
  invalidateLeaderboardCache,
} from '../services/leaderboardCacheService.js';

const router = Router();

const leaderboardPublicLimiter = createRequestRateLimiter({
  keyPrefix: 'rl:leaderboard:public',
  windowSeconds: 60,
  maxRequests: 120,
  identity: 'ip',
});

function parseCohort(cohort) {
  if (!cohort) return {};
  const [branchPart, yearPart] = String(cohort).split('-');
  const branch = branchPart ? branchPart.trim().toUpperCase() : null;
  const year = yearPart ? parseInt(yearPart, 10) : null;

  return {
    branch: branch || null,
    year: Number.isFinite(year) ? year : null,
  };
}

// ─── GET /api/leaderboard — Public, paginated, filterable ───
router.get('/', leaderboardPublicLimiter, async (req, res) => {
  try {
    const {
      page = 1,
      limit = 20,
      branch,
      year,
      tier,
      cohort,
    } = req.query;

    const pageNum = Math.max(1, parseInt(page));
    const limitNum = Math.min(50, Math.max(1, parseInt(limit)));
    const skip = (pageNum - 1) * limitNum;

    // Build filter
    const filter = {};
    const cohortFilter = parseCohort(cohort);

    if (branch || cohortFilter.branch) {
      filter.branch = (branch || cohortFilter.branch).toUpperCase();
    }
    if (year || cohortFilter.year) {
      filter.year = parseInt(year || cohortFilter.year, 10);
    }
    if (tier) filter.tierRank = tier;

    // Only show students who have synced at least once
    filter.score = { $gt: 0 };

    const cacheKey = buildLeaderboardCacheKey('main', {
      page: pageNum,
      limit: limitNum,
      branch: filter.branch,
      year: filter.year,
      tier,
      cohort,
    });

    const cached = await getCachedLeaderboard(cacheKey);
    if (cached) {
      return res.json({ ...cached, cache: { hit: true } });
    }

    const [students, total] = await Promise.all([
      Student.find(filter)
        .select(
          'name enrollmentId branch year score tierRank leaderboardRank avatar githubUsername'
        )
        .sort({ score: -1 })
        .skip(skip)
        .limit(limitNum)
        .lean(),
      Student.countDocuments(filter),
    ]);

    // Compute display rank based on position in sorted results
    const ranked = students.map((student, idx) => ({
      ...student,
      displayRank: skip + idx + 1,
    }));

    const response = {
      students: ranked,
      pagination: {
        page: pageNum,
        limit: limitNum,
        total,
        totalPages: Math.ceil(total / limitNum),
      },
      cache: { hit: false },
    };

    await setCachedLeaderboard(cacheKey, response);
    return res.json(response);
  } catch (error) {
    console.error('Leaderboard error:', error.message);
    return res.status(500).json({ error: 'Failed to load leaderboard' });
  }
});

// ─── GET /api/leaderboard/cohorts/summary — Cohort analytics by branch/year ───
router.get('/cohorts/summary', leaderboardPublicLimiter, async (req, res) => {
  try {
    const { branch, year, tier } = req.query;
    const filter = { score: { $gt: 0 } };
    if (branch) filter.branch = String(branch).toUpperCase();
    if (year) filter.year = parseInt(year, 10);
    if (tier) filter.tierRank = String(tier);

    const cacheKey = buildLeaderboardCacheKey('cohorts_summary', {
      branch: filter.branch,
      year: filter.year,
      tier,
    });

    const cached = await getCachedLeaderboard(cacheKey);
    if (cached) {
      return res.json({ ...cached, cache: { hit: true } });
    }

    const [cohorts, tierDistribution] = await Promise.all([
      Student.aggregate([
        { $match: filter },
        {
          $group: {
            _id: { branch: '$branch', year: '$year' },
            studentCount: { $sum: 1 },
            avgScore: { $avg: '$score' },
            topScore: { $max: '$score' },
          },
        },
        {
          $project: {
            _id: 0,
            cohort: {
              $concat: ['$_id.branch', '-', { $toString: '$_id.year' }],
            },
            branch: '$_id.branch',
            year: '$_id.year',
            studentCount: 1,
            avgScore: { $round: ['$avgScore', 2] },
            topScore: 1,
          },
        },
        { $sort: { branch: 1, year: 1 } },
      ]),
      Student.aggregate([
        { $match: filter },
        {
          $group: {
            _id: '$tierRank',
            count: { $sum: 1 },
          },
        },
        {
          $project: {
            _id: 0,
            tier: '$_id',
            count: 1,
          },
        },
        { $sort: { count: -1 } },
      ]),
    ]);

    const response = {
      cohorts,
      tierDistribution,
      cache: { hit: false },
    };

    await setCachedLeaderboard(cacheKey, response);
    return res.json(response);
  } catch (error) {
    console.error('Cohorts summary error:', error.message);
    return res.status(500).json({ error: 'Failed to load cohort summary' });
  }
});

// ─── GET /api/leaderboard/my-position — Student's rank ± 2 ───
router.get('/my-position', authMiddleware, async (req, res) => {
  try {
    const student = req.user;

    if (!student.score || student.score === 0) {
      return res.json({
        myRank: null,
        message: 'Sync your GitHub profile first to appear on the leaderboard',
        neighbors: [],
      });
    }

    // Get students ranked above (2) and below (2)
    const [above, below] = await Promise.all([
      Student.find({
        score: { $gt: student.score },
        _id: { $ne: student._id },
      })
        .select('name enrollmentId branch score tierRank avatar githubUsername')
        .sort({ score: 1 })
        .limit(2)
        .lean(),
      Student.find({
        score: { $lt: student.score },
        _id: { $ne: student._id },
      })
        .select('name enrollmentId branch score tierRank avatar githubUsername')
        .sort({ score: -1 })
        .limit(2)
        .lean(),
    ]);

    // Calculate ranks for neighbors
    const myRank = student.leaderboardRank;

    const neighbors = [
      ...above.reverse().map((s, i) => ({
        ...s,
        rank: myRank - (above.length - i),
      })),
      {
        _id: student._id,
        name: student.name,
        enrollmentId: student.enrollmentId,
        branch: student.branch,
        score: student.score,
        tierRank: student.tierRank,
        avatar: student.avatar,
        githubUsername: student.githubUsername,
        rank: myRank,
        isMe: true,
      },
      ...below.map((s, i) => ({
        ...s,
        rank: myRank + i + 1,
      })),
    ];

    return res.json({
      myRank,
      myScore: student.score,
      myTier: student.tierRank,
      neighbors,
    });
  } catch (error) {
    console.error('My position error:', error.message);
    return res.status(500).json({ error: 'Failed to get leaderboard position' });
  }
});

// ─── GET /api/leaderboard/my-trends — Authenticated rank + score history ───
router.get('/my-trends', authMiddleware, async (req, res) => {
  try {
    const maxPoints = Math.min(52, Math.max(1, parseInt(req.query.limit, 10) || 12));
    const student = await Student.findById(req.user._id).select(
      'name enrollmentId rankHistory tierRank leaderboardRank score'
    );

    const history = Array.isArray(student?.rankHistory)
      ? student.rankHistory.slice(-maxPoints)
      : [];

    const latest = history.length > 0 ? history[history.length - 1] : null;
    const previous = history.length > 1 ? history[history.length - 2] : null;

    return res.json({
      enrollmentId: student.enrollmentId,
      current: {
        rank: student.leaderboardRank,
        score: student.score,
        tier: student.tierRank,
      },
      trend: {
        rankDelta: latest && previous ? previous.rank - latest.rank : 0,
        scoreDelta: latest && previous ? latest.score - previous.score : 0,
        points: history,
      },
    });
  } catch (error) {
    console.error('My trends error:', error.message);
    return res.status(500).json({ error: 'Failed to load rank trend' });
  }
});

// ─── GET /api/leaderboard/admin/flags — Admin anti-cheat review queue ───
router.get('/admin/flags', authMiddleware, requireAdminKey, async (req, res) => {
  try {
    const {
      status = 'pending',
      branch,
      year,
      page = 1,
      limit = 25,
    } = req.query;

    const pageNum = Math.max(1, parseInt(page, 10) || 1);
    const limitNum = Math.min(100, Math.max(1, parseInt(limit, 10) || 25));
    const skip = (pageNum - 1) * limitNum;

    const filter = { isFlagged: true };
    if (status) filter['antiCheatReview.status'] = status;
    if (branch) filter.branch = String(branch).toUpperCase();
    if (year) filter.year = parseInt(year, 10);

    const [students, total] = await Promise.all([
      Student.find(filter)
        .select(
          'name enrollmentId branch year score tierRank antiCheatFlags antiCheatReview githubUsername'
        )
        .sort({ updatedAt: -1 })
        .skip(skip)
        .limit(limitNum)
        .lean(),
      Student.countDocuments(filter),
    ]);

    const queue = students.map((student) => ({
      ...student,
      flagDetails: explainFlags(student.antiCheatFlags || []),
    }));

    return res.json({
      queue,
      pagination: {
        page: pageNum,
        limit: limitNum,
        total,
        totalPages: Math.ceil(total / limitNum),
      },
    });
  } catch (error) {
    console.error('Admin flag queue error:', error.message);
    return res.status(500).json({ error: 'Failed to load admin anti-cheat queue' });
  }
});

// ─── PATCH /api/leaderboard/admin/flags/:enrollmentId/review — Admin review update ───
router.patch('/admin/flags/:enrollmentId/review', authMiddleware, requireAdminKey, async (req, res) => {
  try {
    const { status = 'reviewed', note = '', clearFlags = false } = req.body || {};
    const allowed = new Set(['pending', 'reviewed', 'escalated']);

    if (!allowed.has(status)) {
      return res.status(400).json({
        error: 'Invalid status. Use pending, reviewed, or escalated.',
      });
    }

    const enrollmentId = String(req.params.enrollmentId || '').toUpperCase();

    const update = {
      antiCheatReview: {
        status,
        reviewedBy: req.user?.email || req.user?.enrollmentId || 'admin',
        note,
        reviewedAt: new Date(),
      },
    };

    if (clearFlags === true) {
      update.antiCheatFlags = [];
      update.isFlagged = false;
    }

    const student = await Student.findOneAndUpdate(
      { enrollmentId },
      update,
      { new: true }
    ).select('name enrollmentId antiCheatFlags isFlagged antiCheatReview');

    if (!student) {
      return res.status(404).json({ error: 'Student not found' });
    }

    await invalidateLeaderboardCache();

    return res.json({
      message: 'Anti-cheat review updated',
      student,
    });
  } catch (error) {
    console.error('Admin flag review update error:', error.message);
    return res.status(500).json({ error: 'Failed to update anti-cheat review' });
  }
});

// ─── GET /api/leaderboard/:enrollmentId/history — Public rank trend endpoint ───
router.get('/:enrollmentId/history', leaderboardPublicLimiter, async (req, res) => {
  try {
    const maxPoints = Math.min(52, Math.max(1, parseInt(req.query.limit, 10) || 26));
    const enrollmentId = String(req.params.enrollmentId || '').toUpperCase();

    const student = await Student.findOne({ enrollmentId }).select(
      'name enrollmentId branch year tierRank leaderboardRank score rankHistory'
    );

    if (!student) {
      return res.status(404).json({ error: 'Student not found' });
    }

    const points = (student.rankHistory || []).slice(-maxPoints);

    return res.json({
      student: {
        name: student.name,
        enrollmentId: student.enrollmentId,
        branch: student.branch,
        year: student.year,
        tierRank: student.tierRank,
        leaderboardRank: student.leaderboardRank,
        score: student.score,
      },
      trend: {
        points,
      },
    });
  } catch (error) {
    console.error('Public history error:', error.message);
    return res.status(500).json({ error: 'Failed to load public rank history' });
  }
});

export default router;
